# Full portable project suite, explicit historical raw/path exclusions.
import os,sys,json,base64,zlib,subprocess,hashlib
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
subprocess.run([sys.executable,'-m','pip','install','pytest','pyarrow','statsmodels'],check=True)
excluded=['tests/test_comp3.py','tests/test_letter_head.py','tests/test_bank_report.py','tests/test_kaggle_kill_test_run.py']
(out/'cloud_test_scope.json').write_text(json.dumps(dict(excluded=excluded,reason='same historical unavailable raw-data and credential-path exclusions; no newly failing test excluded',scope='all current repository Python tests except listed files',git_commit='a0b6cf6d1cae7fda3647033f36362d3c4c656e5d',runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()),indent=2))
cmd=[sys.executable,'-m','pytest','-q','tests']+['--ignore='+name for name in excluded]
result=subprocess.run(cmd,cwd=code,capture_output=True,text=True)
(out/'pytest.txt').write_text(result.stdout+result.stderr);print(result.stdout,flush=True)
(out/'config.json').write_text(json.dumps(dict(seed=20261013,git_commit='a0b6cf6d1cae7fda3647033f36362d3c4c656e5d',returncode=result.returncode,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()),indent=2))
if result.returncode:raise RuntimeError('current portable repository suite failed; inspect rather than weakening checks')
